def main(out_path: str) -> None:
    with open(out_path, "w", newline="") as fh:
        writer = csv.writer(fh)
        writer.writerow(["Test_ID", "Category", "User_Query", "Expected_Condition",
                         "Expected_Age_Band", "Follow_Up_Replies", "Notes"])
        for i, (cat, query, expected, age, follow, notes) in enumerate(ROWS, start=1):
            writer.writerow([f"H{i:03d}", cat, query, expected, age, follow, notes])
    print(f"wrote {len(ROWS)} cases to {out_path}")


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else "heldout_testset_v1.csv")
